using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;

public partial class AudioAnalysisOperations : RefCounted
{
    public int nearest_zero(Vector2[] samples,int at,int radius,int channel)
    {
        if(samples.Length==0)return 0;at=Math.Clamp(at,0,samples.Length-1);int best=at;double score=double.PositiveInfinity;double Sample(int index)=>channel==0?samples[index].X:channel==1?samples[index].Y:(samples[index].X+samples[index].Y)*.5;for(int index=Math.Max(1,at-radius);index<Math.Min(samples.Length,at+radius+1);index++){double a=Sample(index-1),b=Sample(index);double value=Math.Abs(b)+Math.Abs(index-at)*.00002+(a*b<=0?0:1);if(value<score){score=value;best=index;}}return best;
    }
    public Vector2[] edit(Vector2[] samples,string operation,int first,int last,double amount,int channel,Vector2[] clipboard)
    {
        first=Math.Clamp(first,0,samples.Length);last=Math.Clamp(last,first,samples.Length);int count=last-first;if(operation=="trim")return samples[first..last];if(operation=="cut"||operation=="paste"){int inserted=operation=="paste"?clipboard.Length:0;var result=new Vector2[checked(samples.Length-count+inserted)];Array.Copy(samples,0,result,0,first);if(inserted>0)Array.Copy(clipboard,0,result,first,inserted);Array.Copy(samples,last,result,first+inserted,samples.Length-last);return result;}var output=(Vector2[])samples.Clone();if(count<=0)return output;double normalization=1,gain=Mathf.DbToLinear(amount);if(operation=="normalize"){double peak=0;for(int index=first;index<last;index++)peak=Math.Max(peak,channel==0?Math.Abs(samples[index].X):channel==1?Math.Abs(samples[index].Y):Math.Max(Math.Abs(samples[index].X),Math.Abs(samples[index].Y)));normalization=gain/Math.Max(.000001,peak);}for(int index=first;index<last;index++){var old=samples[index];var value=old;double ratio=(double)(index-first)/Math.Max(1,count-1);switch(operation){case "set_amplitude":value=Vector2.One*(float)Math.Clamp(amount,-1,1);break;case "silence":value=Vector2.Zero;break;case "amplify":value*=(float)gain;break;case "normalize":value*=(float)normalization;break;case "reverse":value=samples[last-1-(index-first)];break;case "fade_in":value*=(float)Math.Sin(ratio*Math.PI*.5);break;case "fade_out":value*=(float)Math.Cos(ratio*Math.PI*.5);break;case "repair":value=samples[Math.Max(0,first-1)].Lerp(samples[Math.Min(samples.Length-1,last)],(float)Mathf.SmoothStep(0,1,ratio));break;case "invert":value=-value;break;case "mono":value=Vector2.One*(value.X+value.Y)*.5f;break;}if(channel==0)value.Y=old.Y;else if(channel==1)value.X=old.X;output[index]=value;}return output;
    }
    public Settings alignment(Vector2[] reference,Vector2[] candidate,int rate,double maxOffset)
    {
        int step=Math.Max(1,rate/1000);var a=new List<float>();var b=new List<float>();for(int index=0;index<Math.Min(reference.Length,rate*20);index+=step)a.Add((reference[index].X+reference[index].Y)*.5f);for(int index=0;index<Math.Min(candidate.Length,rate*20);index+=step)b.Add((candidate[index].X+candidate[index].Y)*.5f);int bound=Math.Min(2000,(int)(maxOffset*rate/step));double best=double.NegativeInfinity;int lagBest=0;for(int lag=-bound;lag<=bound;lag++){double cross=0,aa=0,bb=0;int count=0;for(int index=Math.Max(0,-lag);index<Math.Min(a.Count,b.Count-lag);index+=4){cross+=a[index]*b[index+lag];aa+=a[index]*a[index];bb+=b[index+lag]*b[index+lag];count++;}double score=count>30?cross/Math.Sqrt(Math.Max(.000000001,aa*bb)):double.NegativeInfinity;if(score>best){best=score;lagBest=lag;}}return new Settings {["offset"]=-(double)lagBest*step/rate,["confidence"]=Math.Max(0,best)};
    }
    public float[] spectrum(Vector2[] samples,int first,int size)
    {
        size=1<<Math.Clamp((int)Math.Round(Math.Log2(Math.Max(32,size)),MidpointRounding.AwayFromZero),5,13);var real=new double[size];var imaginary=new double[size];for(int index=0;index<size;index++)if(first+index>=0&&first+index<samples.Length)real[index]=(samples[first+index].X+samples[first+index].Y)*.5*(.5-.5*Math.Cos(Math.Tau*index/(size-1)));int j=0;for(int index=1;index<size;index++){int bit=size>>1;while((j&bit)!=0){j^=bit;bit>>=1;}j^=bit;if(index<j)(real[index],real[j])=(real[j],real[index]);}for(int length=2;length<=size;length<<=1){double angle=-Math.Tau/length,wrStep=Math.Cos(angle),wiStep=Math.Sin(angle);for(int start=0;start<size;start+=length){double wr=1,wi=0;for(int k=0;k<length/2;k++){int even=start+k,odd=even+length/2;double tr=wr*real[odd]-wi*imaginary[odd],ti=wr*imaginary[odd]+wi*real[odd];real[odd]=real[even]-tr;imaginary[odd]=imaginary[even]-ti;real[even]+=tr;imaginary[even]+=ti;double next=wr*wrStep-wi*wiStep;wi=wr*wiStep+wi*wrStep;wr=next;}}}var magnitudes=new float[size/2];for(int index=0;index<magnitudes.Length;index++)magnitudes[index]=(float)(Math.Sqrt(real[index]*real[index]+imaginary[index]*imaginary[index])*4/size);return magnitudes;
    }
    public double remap_edit_boundary(double position,double first,double last,double inserted){if(position<=first)return position;if(position>=last)return position+inserted-(last-first);return first+(position-first)/Math.Max(1,last-first)*inserted;}
}
